INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PT', 'IN-AP', '2025-v1', '2025-04-01', NULL, '{"kind":"pt","basis":"monthly","annualCap":"2500","slabs":[{"from":"0","to":"15000","amount":"0"},{"from":"15000.01","to":"20000","amount":"150"},{"from":"20000.01","to":null,"amount":"200"}]}', 'Andhra Pradesh Tax on Professions, Trades, Callings and Employments Act, 1987, First Schedule entry 1 (official): https://apct.gov.in/apportal/AllActs/APPT/APPTSchedule.aspx . Monthly: up to 15,000 nil; 15,001 to 20,000 = 150; above 20,000 = 200. Read 17 Nov 2026; verify until the CA confirms (checklist items 3 and 24).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
